const wiersze = function (n) { return $(n).all().map(function (i) { return i.json; }).filter(function (r) { return r && r.id; }); };
const ust = {};
wiersze('Pobierz ustawienia').forEach(function (r) { ust[r.klucz] = r.wartosc; });
const teraz = DateTime.now();
const kampanie = wiersze('Pobierz kampanie');
const firmy = wiersze('Pobierz firmy w kolejce');
const plan = { akcja: 'nic', kampania: null, firma: null, kampanieZmiany: [], firmyZmiany: [], powod: '' };
if (ust.system_wstrzymany === 'tak') { plan.powod = 'system wstrzymany'; return [{ json: plan }]; }
const data = function (v) { return v ? DateTime.fromISO(String(v)) : null; };
const aktywne = [];
kampanie.forEach(function (k) {
  if (k.status !== 'aktywna') return;
  const koniec = data(k.data_koniec);
  if (koniec && koniec < teraz) { plan.kampanieZmiany.push({ kampania_id: k.kampania_id, status: 'zakonczona', powiadom: 'Kampania „' + k.branza + ' · ' + k.miasto + '” zakończyła się zgodnie z planem.' }); return; }
  aktywne.push(k);
});
const dozwolone = {};
kampanie.forEach(function (k) { if (k.status === 'aktywna' || k.status === 'wyczerpana') dozwolone[k.kampania_id] = true; });
plan.kampanieZmiany.forEach(function (z) { delete dozwolone[z.kampania_id]; });
firmy.forEach(function (f) {
  if (f.status === 'w_researchu') {
    const blok = data(f.zablokowano);
    if (!blok || blok < teraz.minus({ minutes: 30 })) plan.firmyZmiany.push({ id: f.id, status: (f.proby || 0) >= 3 ? 'odrzucona' : 'nowa', powod: (f.proby || 0) >= 3 ? 'powtarzające się błędy techniczne' : '' });
  }
  if (f.status === 'sprawdz_pozniej') {
    const kiedy = data(f.data_nastepnego);
    if (!kiedy || kiedy <= teraz) plan.firmyZmiany.push({ id: f.id, status: 'nowa', powod: '' });
  }
  if (f.status === 'nowa' && (f.proby || 0) >= 3) plan.firmyZmiany.push({ id: f.id, status: 'odrzucona', powod: 'powtarzające się błędy techniczne' });
});
const zmienione = {};
plan.firmyZmiany.forEach(function (z) { zmienione[z.id] = true; });
const nowe = firmy.filter(function (f) { return f.status === 'nowa' && !zmienione[f.id] && dozwolone[f.kampania_id]; }).sort(function (a, b) { return ((a.strona ? 0 : 1) - (b.strona ? 0 : 1)) || (a.id - b.id); });
const limitDomyslny = parseInt(ust.limit_dzienny || '30', 10);
const dniBufora = parseInt(ust.bufor_dni || '3', 10);
aktywne.forEach(function (k) {
  let warianty = [];
  try { warianty = JSON.parse(k.warianty || '[]'); } catch (e) { warianty = []; }
  k._wariantow = warianty.length;
  k._mozeSzukac = (k.wariant_idx || 0) < warianty.length || !k.osm_pobrane;
  const jejNowe = firmy.filter(function (f) { return f.kampania_id === k.kampania_id && (f.status === 'nowa' || f.status === 'w_researchu'); }).length;
  if (!k._mozeSzukac && jejNowe === 0) plan.kampanieZmiany.push({ kampania_id: k.kampania_id, status: 'wyczerpana', powiadom: 'Kampania „' + k.branza + ' · ' + k.miasto + '”: system sprawdził już wszystkie firmy, które dało się znaleźć. Gotowe maile nadal będą wysyłane. Warto uruchomić nową kampanię.' });
});
const kandydaci = kampanie.filter(function (k) { return dozwolone[k.kampania_id]; }).map(function (k) {
  const akt = aktywne.filter(function (a) { return a.kampania_id === k.kampania_id; })[0] || null;
  const lim = parseInt(k.limit_dzienny, 10) || limitDomyslny;
  const gotoweK = firmy.filter(function (f) { return f.kampania_id === k.kampania_id && f.status === 'gotowa'; }).length;
  const noweK = nowe.filter(function (f) { return f.kampania_id === k.kampania_id; });
  const ost = data(k.ostatnie_szukanie);
  const mozeSzukac = !!akt && akt._mozeSzukac && (!ost || ost < teraz.minus({ minutes: 4 }));
  return { kampania: akt || k, lim: lim, gotowe: gotoweK, nowe: noweK, mozeSzukac: mozeSzukac, zapas: gotoweK / lim };
}).filter(function (c) { return c.gotowe < c.lim * dniBufora && (c.nowe.length || c.mozeSzukac); }).sort(function (a, b) { return a.zapas - b.zapas; });
if (!kandydaci.length) { plan.powod = 'zapas gotowych maili wystarczy albo brak firm do sprawdzenia'; return [{ json: plan }]; }
const wybrana = kandydaci[0];
if (wybrana.nowe.filter(function (f) { return !!f.strona; }).length < 5 && wybrana.mozeSzukac) {
  plan.akcja = 'szukaj';
  plan.kampania = wybrana.kampania;
} else if (wybrana.nowe.length) {
  plan.akcja = 'research';
  plan.firma = wybrana.nowe[0];
} else {
  plan.akcja = 'szukaj';
  plan.kampania = wybrana.kampania;
}
return [{ json: plan }];

