const HOST = function (u) { const m = String(u || '').match(/^https?:\/\/([^\/?#:]+)/i); return m ? m[1].toLowerCase().replace(/^www\./, '') : ''; };
const SCIEZKA = function (u) { return String(u || '').replace(/^https?:\/\/[^\/?#]+/i, '').split('#')[0].split('?')[0] || '/'; };
const ABS = function (href, baza) {
  href = String(href || '').trim();
  if (!href || /^(mailto:|tel:|javascript:|data:)/i.test(href)) return '';
  if (/^https?:\/\//i.test(href)) return href;
