const czytelna = status >= 200 && status < 400 && tekst.length >= 500 && !/(enable javascript|włącz javascript|wymaga włączonego javascript)/i.test(tekst.slice(0, 2000));
const KLUCZE = [['kontakt', 10], ['contact', 10], ['o-nas', 7], ['o-firmie', 7], ['about', 6], ['oferta', 5], ['uslugi', 5], ['usługi', 5], ['cennik', 4], ['polityka', 3], ['prywatnosc', 3], ['rodo', 3], ['regulamin', 2], ['zespol', 2], ['faq', 2]];
