  if (!punkty) continue;
  const klucz = POCZ(abs) + sc;
  if (!linki[klucz] || linki[klucz] < punkty) linki[klucz] = punkty;
}
const glowna = POCZ(w.strona) + SCIEZKA(w.strona);
const podstrony = Object.keys(linki).filter(function (u) { return u !== glowna; }).sort(function (a, b) { return linki[b] - linki[a]; }).slice(0, 4);
return [{ json: { czytelna: czytelna, status: status, html: html.slice(0, 400000), podstrony: podstrony } }];

