const dekoduj = function (t) { return t.replace(/&#(\d+);/g, function (a, n) { return String.fromCharCode(parseInt(n, 10)); }).replace(/&#x([0-9a-f]+);/gi, function (a, n) { return String.fromCharCode(parseInt(n, 16)); }).replace(/&([a-z]+);/gi, function (a, n) { return encje[n] !== undefined ? encje[n] : a; }); };
const cfemail = function (hex) { try { const k = parseInt(hex.substr(0, 2), 16); let o = ''; for (let i = 2; i < hex.length; i += 2) o += String.fromCharCode(parseInt(hex.substr(i, 2), 16) ^ k); return o; } catch (e) { return ''; } };
