const widzety = [];
const WIDZETY = [['booksy', 'zapisy online przez Booksy'], ['momentapp', 'zapisy online (Moment)'], ['moment.pl', 'zapisy online (Moment)'], ['versum', 'zapisy online (Versum)'], ['fresha', 'zapisy online (Fresha)'], ['znanylekarz', 'zapisy przez ZnanyLekarz'], ['docplanner', 'zapisy przez ZnanyLekarz'], ['calendly', 'zapisy online (Calendly)'], ['tidio', 'czat na stronie (Tidio)'], ['smartsupp', 'czat na stronie (Smartsupp)'], ['livechat', 'czat na stronie (LiveChat)'], ['tawk.to', 'czat na stronie (Tawk)'], ['crisp.chat', 'czat na stronie (Crisp)'], ['customerchat', 'czat Messenger na stronie'], ['zendesk', 'czat lub helpdesk (Zendesk)'], ['bookero', 'zapisy online (Bookero)'], ['reservio', 'zapisy online (Reservio)'], ['medfile', 'rejestracja online (Medfile)'], ['simplybook', 'zapisy online (SimplyBook)']];
