const esc = function (t) { return String(t == null ? '' : t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const ocen = function (opis, nazwaNode) {
  const m = String(opis || '').toLowerCase();
  const n = String(nazwaNode || '').toLowerCase();
  let usluga = 'jedną z usług';
  if (n.indexOf('gmail') !== -1) usluga = 'Gmailem';
  else if (n.indexOf('ai:') !== -1 || m.indexOf('openai') !== -1) usluga = 'OpenAI';
  else if (n.indexOf('google') !== -1) usluga = 'Google Maps';
  else if (n.indexOf('firecrawl') !== -1) usluga = 'Firecrawlem';
  else if (n.indexOf('telegram') !== -1) usluga = 'Telegramem';
  else if (/pobierz|zapisz|oznacz|zaktualizuj|usu|firma z|ostatnie|dzisiejsze|gotowe|follow|powroty|raport|odpowiedzi|już obsłużone/.test(n)) usluga = 'bazą danych n8n';
  if (/\b(401|403)\b|unauthori|forbidden|invalid_grant|invalid.{0,20}(credential|token|api.?key)|credentials? (are|is) (invalid|wrong)|permission|token has been expired|revoked/.test(m)) {
    return { powazny: true, klucz: 'auth:' + usluga, co: 'Przestało działać połączenie z ' + usluga + ' (wygasło logowanie albo klucz).', rada: 'Wejdź w n8n → Credentials i połącz to konto ponownie. Dopóki tego nie zrobisz, ta część systemu stoi.' };
  }
  if (/insufficient_quota|billing|credit balance|exceeded your current quota|\b402\b|payment required|daily sending quota|daily user sending limit|user-rate limit exceeded/.test(m)) {
    return { powazny: true, klucz: 'limit:' + usluga, co: usluga === 'Gmailem' ? 'Gmail zablokował wysyłkę na dziś (za dużo maili).' : 'Skończyły się środki albo limit na koncie (' + usluga + ').', rada: usluga === 'Gmailem' ? 'Wyłącz system przyciskiem poniżej i zmniejsz limity kampanii. Gmail odblokuje się zwykle po 24 godzinach.' : 'Doładuj konto albo zwiększ limit w tej usłudze. Do tego czasu ta część systemu stoi.' };
  }
  if (/timeout|timed out|etimedout|econnreset|econnrefused|enotfound|socket hang up|\b50[0234]\b|unavailable|bad gateway|overloaded|\b429\b|rate.?limit|too many requests/.test(m)) {
    return { powazny: false, klucz: 'chwilowy:' + usluga, co: 'Połączenie z ' + usluga + ' ciągle nie działa (serwis nie odpowiada albo jest przeciążony).', rada: 'Zwykle przechodzi samo. Jeśli dostaniesz ten alert jeszcze raz, sprawdź stronę statusu tej usługi.' };
  }
  return { powazny: false, klucz: 'inny:' + n, co: 'Ten sam błąd powtarza się w kroku „' + nazwaNode + '”.', rada: 'Pojedyncze przypadki system pomija sam. Skoro się powtarza, warto rzucić okiem w n8n (lista wykonań tego workflowu).' };
};
const s = $getWorkflowStaticData('global');
const teraz = Date.now();
s.bledy = s.bledy || {};
s.zgloszone = s.zgloszone || {};
const PROG_POWTORZEN = 4;
const ex = $input.first().json.execution || {};
const blad = ex.error || {};
const nazwa = (blad.node || {}).name || ex.lastNodeExecuted || '';
const opis = String(blad.message || '') + ' ' + String(blad.description || '') + ' ' + JSON.stringify(blad).slice(0, 2000);
const o = ocen(opis, nazwa);
const lista = (s.bledy[o.klucz] || []).filter(function (t) { return teraz - t < 3600000; });
lista.push(teraz);
s.bledy[o.klucz] = lista;
Object.keys(s.bledy).forEach(function (k) { s.bledy[k] = s.bledy[k].filter(function (t) { return teraz - t < 3600000; }); if (!s.bledy[k].length) delete s.bledy[k]; });
if (!o.powazny && lista.length < PROG_POWTORZEN) return [];
if (s.zgloszone[o.klucz] && teraz - s.zgloszone[o.klucz] < 3 * 3600000) return [];
s.zgloszone[o.klucz] = teraz;
const naglowek = o.powazny ? '🚨 <b>Silnik researchu: poważny problem</b>' : '⚠️ <b>Silnik researchu: problem się powtarza</b> (' + lista.length + 'x w ostatniej godzinie)';
return [{ json: { tekst: naglowek + '\n\n<b>Co się stało:</b> ' + esc(o.co) + '\n<b>Co zrobić:</b> ' + esc(o.rada) + '\n\n<i>Szczegóły: ' + esc(nazwa) + ' – ' + esc(String(blad.message || '').slice(0, 180)) + '</i>\n\nPrzycisk poniżej zatrzymuje cały system (szukanie, research i wysyłkę). Ten sam problem nie będzie zgłaszany częściej niż co 3 godziny.' } }];
